package io.github.anatoliisennikov.rtkey.model;

import org.jspecify.annotations.Nullable;

import java.time.Instant;
import java.util.List;

/**
 * A door code generated by
 * {@link io.github.anatoliisennikov.rtkey.CodeService#generateCode(int, int)}.
 *
 * @param id          code identifier
 * @param codeType    code type reported by the server; the API uses the wire values
 *                    {@code temporary} and {@code emergency}
 * @param code        the generated code value
 * @param title       code title, when set
 * @param expiresAt   expiration timestamp
 * @param roomId      flat identifier ({@code flats[].id})
 * @param deviceIds   identifiers of the devices the code was generated for
 * @param ownerUserId identifier of the user the code belongs to
 * @param createdAt   creation timestamp
 */
public record GeneratedCode(
        Integer id,
        String codeType,
        String code,
        @Nullable
        String title,
        Instant expiresAt,
        Integer roomId,
        List<Integer> deviceIds,
        Integer ownerUserId,
        Instant createdAt
) {
}
